fn ls_for_one_pattern(
    pattern_arg: Option<Spanned<NuGlob>>,
    args: Args,
    signals: &Signals,
    cwd: PathBuf,
) -> Result<Box<dyn Iterator<Item = Value> + Send>, ShellError> {
    let Args {
        all,
        long,
        short_names,
        full_paths,
        du,
        directory,
        use_mime_type,
        call_span,
    } = args;
    let lister = Ls::default();
    let pattern_arg = lister.normalize_pattern_arg(pattern_arg)?;

    let mut just_read_dir = false;
    let p_tag: Span = lister.pattern_span_or_call(pattern_arg.as_ref(), call_span);
    let (pattern_arg, absolute_path) = match pattern_arg {
        Some(pat) => {
            // expand with cwd here is only used for checking
            let tmp_expanded = lister.expanded_listing_path(&pat.item, &cwd);
            // Avoid checking and pushing "*" to the path when directory (do not show contents) flag is true
            if !directory && tmp_expanded.is_dir() {
                if Ls::permission_is_denied(&tmp_expanded) {
                    return Err(lister.permission_denied_error(&tmp_expanded, p_tag));
                }
                if Ls::directory_is_empty(&tmp_expanded) {
                    return Ok(Box::new(vec![].into_iter()));
                }
                just_read_dir = Ls::should_read_directory_directly(&pat.item, &tmp_expanded, directory, lister.pattern_has_glob_meta(pat.item.as_ref()));
            }

            // it's absolute path if:
            // 1. pattern is absolute.
            // 2. pattern can be expanded, and after expands to real_path, it's absolute.
            //    here `expand_to_real_path` call is required, because `~/aaa` should be absolute
            //    path.
            let absolute_path = lister.resolve_pattern_absolute(&pat.item);
            (pat.item, absolute_path)
        }
        None => {
            // Avoid pushing "*" to the default path when directory (do not show contents) flag is true
            if directory {
                (NuGlob::Expand(".".to_string()), false)
            } else if Ls::directory_is_empty(&cwd) {
                return Ok(Box::new(vec![].into_iter()));
            } else {
                (NuGlob::Expand("*".to_string()), false)
            }
        }
    };

    let hidden_dir_specified = Ls::hidden_dir_specified_from_pattern(pattern_arg.as_ref());
    let path = pattern_arg.into_spanned(p_tag);
    let (prefix, paths) = if just_read_dir {
        let expanded = nu_path::expand_path_with(path.item.as_ref(), &cwd, path.item.is_expand());
        let paths = Ls::read_directory_paths(&expanded)?;
        // just need to read the directory, so prefix is path itself.
        (Some(expanded), paths)
    } else {
        let glob_options = lister.glob_match_options_for(all);
        glob_from(&path, &cwd, call_span, glob_options)?
    };

    let mut paths_peek = paths.peekable();
    if paths_peek.peek().is_none() {
        return Err(lister.no_matches_error(&path.item, p_tag));
    }

    let mut hidden_dirs = vec![];

    let signals = signals.clone();
    let lister = lister.clone();
    Ok(Box::new(paths_peek.filter_map(move |x| match x {
        Ok(path) => {
            let metadata = lister.symlink_metadata_or_none(&path);
            if lister.skip_hidden_listing_path(&path, all, hidden_dir_specified, &mut hidden_dirs) {
                return None;
            }

            let display_name = lister
                .display_name_for(
                    &path,
                    short_names,
                    full_paths,
                    absolute_path,
                    directory,
                    prefix.as_ref(),
                    &cwd,
                )
                .ok_or_else(|| lister.invalid_file_name_error(&path, call_span));

            match display_name {
                Ok(name) => {
                    let entry = dir_entry_dict(
                        &path,
                        &name,
                        metadata.as_ref(),
                        call_span,
                        long,
                        du,
                        &signals,
                        use_mime_type,
                    );
                    match entry {
                        Ok(value) => Some(value),
                        Err(err) => Some(Value::error(err, call_span)),
                    }
                }
                Err(err) => Some(Value::error(err, call_span)),
            }
        }
        Err(err) => Some(Value::error(err, call_span)),
    })))
}

